-- =============================================================================
-- Customer reviews (copied by the owner from the business's Google reviews)
--
-- Reviews are never generated by the site: an admin enters real reviews
-- exactly as written on Google (reviewer name, stars, text, date). Only
-- published reviews are visible to visitors.
-- The 'google_reviews' setting holds the link to the Google reviews page and,
-- optionally, the overall rating and review count shown on Google.
-- =============================================================================

create table public.reviews (
  id           uuid primary key default gen_random_uuid(),
  author_name  text        not null check (char_length(btrim(author_name)) between 1 and 80),
  rating       smallint    not null check (rating between 1 and 5),
  body         text        not null check (char_length(btrim(body)) between 1 and 1500),
  review_date  date,
  source       text        not null default 'google' check (source in ('google')),
  is_published boolean     not null default true,
  sort_order   integer     not null default 0,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create index reviews_published_idx on public.reviews (is_published, sort_order);

create trigger reviews_set_updated_at
  before update on public.reviews
  for each row execute function public.set_updated_at();

alter table public.reviews enable row level security;

revoke all on public.reviews from anon, authenticated;
grant select on public.reviews to anon;
grant select, insert, update, delete on public.reviews to authenticated;

create policy "reviews: public read published"
  on public.reviews for select to anon
  using (is_published);

create policy "reviews: read published or admin"
  on public.reviews for select to authenticated
  using (is_published or (select public.is_admin()));

create policy "reviews: admin insert"
  on public.reviews for insert to authenticated
  with check ((select public.is_admin()));

create policy "reviews: admin update"
  on public.reviews for update to authenticated
  using ((select public.is_admin()))
  with check ((select public.is_admin()));

create policy "reviews: admin delete"
  on public.reviews for delete to authenticated
  using ((select public.is_admin()));

-- Link to the Google reviews page (+ optional overall rating and count, as shown on Google).
insert into public.settings (key, value, is_public)
values ('google_reviews', '{"url": "", "rating": null, "count": null}', true)
on conflict (key) do nothing;

-- Allow reordering reviews from the admin.
create or replace function public.admin_set_sort_order(p_table text, p_ids uuid[])
returns void
language plpgsql
set search_path = ''
as $$
begin
  perform public.assert_admin();
  if p_table not in ('categories', 'hero_slides', 'product_images', 'product_options', 'product_variants', 'delivery_zones', 'reviews') then
    raise exception using errcode = 'P0001', message = 'INVALID_TABLE';
  end if;
  execute format(
    'update public.%I t set sort_order = x.pos from unnest($1) with ordinality as x(id, pos) where t.id = x.id',
    p_table
  ) using p_ids;
end;
$$;
